// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;

    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        // live access-control counterparty; grant setLimits for the proxy
        LiveAccessControl ac = new LiveAccessControl();

        // C's constructor disables initializers, so initialize through a minimal proxy
        MinimalProxy proxy = new MinimalProxy(address(c));
        (bool okInit, ) = address(proxy).call(
            abi.encodeWithSignature("initialize(address)", address(ac))
        );
        assertTrue(okInit, "initialize should succeed");

        ac.grantAccess(VaultAdapter.setLimits.selector, address(proxy), actor);

        vm.prank(actor);
        (bool okSet, ) = address(proxy).call(
            abi.encodeWithSignature("setLimits(uint256,uint256,uint256)", uint256(1), uint256(1), uint256(1))
        );
        assertTrue(okSet, "granted setLimits must succeed after initialize");
    }
}

contract MinimalProxy {
    constructor(address impl) {
        assembly {
            sstore(0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc, impl)
        }
    }

    fallback() external payable {
        assembly {
            let impl := sload(0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc)
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    receive() external payable {}
}

contract LiveAccessControl {
    mapping(bytes4 => mapping(address => mapping(address => bool))) public granted;

    function grantAccess(bytes4 _selector, address _contract, address _address) external {
        granted[_selector][_contract][_address] = true;
    }

    function checkAccess(bytes4 _selector, address _contract, address _caller)
        external
        view
        returns (bool hasAccess)
    {
        return granted[_selector][_contract][_caller];
    }

    function role(bytes4, address) external pure returns (bytes32) {
        return bytes32(0);
    }
}
